/**
 * Dashboard cereri de suport — Cloudflare Worker
 *
 * Afișează dashboard-ul la o singură adresă, protejat cu parolă, și descarcă datele de pe oformo.com
 * pe server (fără restricția CORS din browser). Link-ul de export cu token NU este în acest cod:
 * se păstrează ca secret în Cloudflare.
 *
 * Secrete necesare (Cloudflare → Worker → Settings → Variables and Secrets → Add → tip „Secret”):
 *   OFORMO_URL          link-ul complet de export CSV din oformo (cel cu token=...)
 *   DASHBOARD_PASSWORD  parola de acces la dashboard (minim 12 caractere)
 */

const COOKIE = 'dash_session';
const SESSION_DAYS = 30;
const DASHBOARD_HTML = "<!doctype html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cereri de suport — Dashboard</title>\n<style>\n:root{\n  color-scheme: light;\n  --bg:#f4f3f0; --surface:#fcfcfb; --surface-2:#f0efec; --hover:rgba(11,11,11,.035);\n  --border:#e4e3de; --border-strong:#cfcec8;\n  --text:#0b0b0b; --text-2:#52514e; --text-3:#76756f;\n  --accent:#2a78d6; --accent-ink:#1c5cab; --accent-soft:#e6f0fc;\n  --s1:#2a78d6; --s2:#eb6834; --s3:#1baf7a; --s4:#eda100; --s5:#e87ba4; --s6:#008300; --s7:#6250d6; --s8:#e34948;\n  --neutral:#a3a29c; --bar:#2a78d6;\n  --err-bg:#fdeeee; --err-border:#f1c4c4; --err-ink:#a32626;\n  --info-bg:#eef4fc; --info-border:#c9dcf5;\n  --warn-soft:#fff2d4; --warn-ink:#7a5000;\n  --tip-bg:#1d1d1c; --tip-text:#f6f5f2;\n  --shadow:0 1px 2px rgba(0,0,0,.04),0 6px 20px rgba(0,0,0,.035);\n  --radius:12px;\n}\n@media (prefers-color-scheme: dark){\n  :root:where(:not([data-theme=\"light\"])){\n    color-scheme: dark;\n    --bg:#121211; --surface:#1a1a19; --surface-2:#232322; --hover:rgba(255,255,255,.045);\n    --border:#2c2c2a; --border-strong:#3e3e3b;\n    --text:#f0efec; --text-2:#c3c2b7; --text-3:#94938b;\n    --accent:#3987e5; --accent-ink:#86b6ef; --accent-soft:rgba(57,135,229,.16);\n    --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500; --s5:#d55181; --s6:#008300; --s7:#9085e9; --s8:#e66767;\n    --neutral:#6b6a65; --bar:#3987e5;\n    --err-bg:#2a1717; --err-border:#5a2b2b; --err-ink:#f19a9a;\n    --info-bg:#16212f; --info-border:#24405f;\n    --warn-soft:rgba(250,178,25,.14); --warn-ink:#f5c454;\n    --tip-bg:#f0efec; --tip-text:#121211;\n    --shadow:0 1px 2px rgba(0,0,0,.3);\n  }\n}\n:root[data-theme=\"dark\"]{\n  color-scheme: dark;\n  --bg:#121211; --surface:#1a1a19; --surface-2:#232322; --hover:rgba(255,255,255,.045);\n  --border:#2c2c2a; --border-strong:#3e3e3b;\n  --text:#f0efec; --text-2:#c3c2b7; --text-3:#94938b;\n  --accent:#3987e5; --accent-ink:#86b6ef; --accent-soft:rgba(57,135,229,.16);\n  --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500; --s5:#d55181; --s6:#008300; --s7:#9085e9; --s8:#e66767;\n  --neutral:#6b6a65; --bar:#3987e5;\n  --err-bg:#2a1717; --err-border:#5a2b2b; --err-ink:#f19a9a;\n  --info-bg:#16212f; --info-border:#24405f;\n  --warn-soft:rgba(250,178,25,.14); --warn-ink:#f5c454;\n  --tip-bg:#f0efec; --tip-text:#121211;\n  --shadow:0 1px 2px rgba(0,0,0,.3);\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml,body{margin:0}\nbody{background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;-webkit-font-smoothing:antialiased}\na{color:var(--accent-ink)}\n.wrap{max-width:1320px;margin:0 auto;padding:22px 16px 48px}\n@media(min-width:760px){.wrap{padding:28px 28px 56px}}\n\n/* Header */\n.top{display:flex;flex-wrap:wrap;gap:14px 20px;align-items:flex-end;justify-content:space-between;margin-bottom:18px}\nh1{font-size:22px;line-height:1.2;margin:0 0 6px;font-weight:650;letter-spacing:-.01em}\n.meta{color:var(--text-2);font-size:13px}\n.live-dot{width:8px;height:8px;border-radius:50%;background:var(--neutral);display:inline-block;margin-right:7px;vertical-align:1px}\n.live-dot.live{background:#0ca30c}\n.live-dot.cache{background:#fab219}\n.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.btn{height:36px;padding:0 14px;border-radius:8px;border:1px solid var(--border-strong);background:var(--surface);color:var(--text);font:inherit;font-weight:550;display:inline-flex;align-items:center;gap:8px;cursor:pointer;text-decoration:none;white-space:nowrap}\n.btn:hover{background:var(--surface-2)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{filter:brightness(1.07)}\n.btn.sm{height:30px;padding:0 10px;font-size:13px}\n.btn svg{width:16px;height:16px;flex:0 0 auto}\n.btn[disabled]{cursor:progress;opacity:.8}\n.btn.loading svg.spin{animation:spin .8s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n:is(button,a,input,select,[tabindex]):focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.ctl{height:36px;border:1px solid var(--border-strong);border-radius:8px;background:var(--surface);color:var(--text);padding:0 10px;font:inherit;min-width:0;max-width:100%}\n.auto{display:inline-flex;align-items:center;gap:6px;color:var(--text-2);font-size:13px}\n.auto .ctl{height:36px}\n\n/* Banner */\n.banner{display:none;gap:12px;align-items:flex-start;padding:14px 16px;border-radius:var(--radius);border:1px solid var(--info-border);background:var(--info-bg);margin-bottom:16px}\n.banner.show{display:flex}\n.banner.error{background:var(--err-bg);border-color:var(--err-border)}\n.banner .ic{flex:0 0 auto;width:20px;height:20px;margin-top:1px}\n.banner.error .ic{color:var(--err-ink)}\n.banner b{display:block;margin-bottom:2px}\n.banner p{margin:0;color:var(--text-2);font-size:13.5px}\n.banner .ba{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}\n\n/* KPIs */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:16px}\n.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow)}\n.kpi{padding:14px 16px;text-align:left;font:inherit;color:inherit;width:100%}\n.kpi .l{font-size:12.5px;color:var(--text-2);font-weight:550}\n.kpi .v{font-size:28px;font-weight:650;letter-spacing:-.02em;font-variant-numeric:tabular-nums;margin-top:4px;line-height:1.1}\n.kpi .s{font-size:12px;color:var(--text-3);margin-top:5px}\nbutton.kpi{cursor:pointer}\nbutton.kpi:hover{background:var(--surface-2)}\n.kpi.active{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}\n\n/* Filters */\n.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:12px;margin-bottom:16px}\n.search{position:relative;flex:1 1 260px;min-width:200px}\n.search input{width:100%;padding-left:34px}\n.search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--text-3);pointer-events:none}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{height:32px;padding:0 12px;border-radius:999px;border:1px solid var(--border-strong);background:var(--surface);color:var(--text);display:inline-flex;align-items:center;gap:7px;font:inherit;font-size:13px;cursor:pointer}\n.chip:hover{background:var(--surface-2)}\n.chip[aria-pressed=\"true\"]{background:var(--accent-soft);border-color:var(--accent)}\n.chip .dot{width:8px;height:8px;border-radius:50%}\n.chip .n{color:var(--text-3);font-variant-numeric:tabular-nums}\n#fInst{flex:0 1 320px;min-width:170px}\n#fMonth{flex:0 0 auto}\n.linkbtn{background:none;border:0;color:var(--accent-ink);font:inherit;font-size:13px;cursor:pointer;padding:6px 4px;font-weight:550}\n.linkbtn[hidden]{display:none}\n\n/* Charts */\n.charts{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px;margin-bottom:16px}\n.c-status{grid-column:span 4}.c-month{grid-column:span 8}.c-inst{grid-column:span 12}\n@media(max-width:980px){.c-status,.c-month,.c-inst{grid-column:span 12}}\n.panel{padding:16px 16px 14px;min-width:0}\n.panel h2{font-size:14.5px;font-weight:620;margin:0}\n.panel .hint{font-size:12px;color:var(--text-3);margin:2px 0 14px}\n.nodata{color:var(--text-3);font-size:13px;padding:24px 0;text-align:center}\n.dim{opacity:.38}\n\n.seg{display:flex;gap:2px;height:14px;margin:4px 0 12px}\n.seg span{min-width:3px;height:100%;cursor:pointer}\n.seg span:first-child{border-radius:4px 0 0 4px}\n.seg span:last-child{border-radius:0 4px 4px 0}\n.seg span:only-child{border-radius:4px}\n.srow{display:grid;grid-template-columns:10px minmax(0,1fr) auto 42px;gap:10px;align-items:center;width:100%;padding:7px 8px;border-radius:8px;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}\n.srow:hover{background:var(--hover)}\n.srow.sel{background:var(--accent-soft)}\n.srow .sw{width:10px;height:10px;border-radius:3px}\n.srow .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.srow .cnt{font-variant-numeric:tabular-nums;font-weight:620}\n.srow .pct{color:var(--text-3);font-size:12px;text-align:right;font-variant-numeric:tabular-nums}\n\n.cc-plot{position:relative;height:200px;margin-top:22px}\n.cc-grid div{position:absolute;left:30px;right:0;height:0;border-top:1px solid var(--border)}\n.cc-grid div.base{border-top-color:var(--border-strong)}\n.cc-grid span{position:absolute;right:calc(100% + 7px);top:-8px;font-size:11px;color:var(--text-3);font-variant-numeric:tabular-nums}\n.cc-cols{position:absolute;left:30px;right:0;top:0;bottom:0;display:flex;align-items:flex-end;gap:6px}\n.cc-col{flex:1 1 0;min-width:0;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;background:none;border:0;padding:0;cursor:pointer;border-radius:6px 6px 0 0}\n.cc-col:hover{background:var(--hover)}\n.cc-bar{width:100%;max-width:46px;background:var(--bar);border-radius:4px 4px 0 0}\n.cc-val{font-size:11.5px;color:var(--text-2);margin-bottom:4px;font-variant-numeric:tabular-nums;font-weight:600}\n.cc-x{display:flex;gap:6px;margin:7px 0 0 30px}\n.cc-x span{flex:1 1 0;min-width:0;text-align:center;font-size:11px;color:var(--text-3);line-height:1.25;white-space:nowrap;overflow:hidden}\n\n.ilist{max-height:430px;overflow-y:auto;margin:0 -8px}\n.irow{display:grid;grid-template-columns:minmax(0,36%) minmax(0,1fr) 44px;gap:14px;align-items:center;width:100%;padding:6px 8px;border:0;border-radius:8px;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}\n.irow:hover{background:var(--hover)}\n.irow.sel{background:var(--accent-soft)}\n.irow .nm{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.irow .tr{height:12px;display:flex}\n.irow .b{height:100%;background:var(--bar);border-radius:0 4px 4px 0;min-width:3px}\n.irow .c{text-align:right;font-variant-numeric:tabular-nums;font-weight:620}\n@media(max-width:640px){\n  .irow{grid-template-columns:minmax(0,1fr) 36px;grid-template-areas:\"nm c\" \"tr tr\";row-gap:5px}\n  .irow .nm{grid-area:nm;white-space:normal}.irow .tr{grid-area:tr}.irow .c{grid-area:c}\n}\n\n/* Table */\n.thead{display:flex;flex-wrap:wrap;gap:8px 12px;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid var(--border)}\n.thead h2{font-size:14.5px;margin:0;font-weight:620}\n.thead .cnt{color:var(--text-3);font-weight:500;margin-left:4px}\n.tscroll{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;min-width:1020px}\nth{font-size:12px;font-weight:600;color:var(--text-2);text-align:left;padding:10px 12px;border-bottom:1px solid var(--border);white-space:nowrap;user-select:none;background:var(--surface-2)}\nth button{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:4px}\nth button:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:3px}\nth .ar{opacity:.55;font-size:10px}\nth.num,td.num{text-align:right}\nth.num button{justify-content:flex-end}\ntd{padding:10px 12px;border-bottom:1px solid var(--border);vertical-align:top;font-size:13.5px}\ntbody tr{cursor:pointer}\ntbody tr:hover{background:var(--hover)}\ntbody tr:last-child td{border-bottom:0}\n.clamp{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\ntd.t-date{white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--text-2)}\ntd.t-title{min-width:300px;max-width:480px;font-weight:520}\ntd.t-inst{min-width:190px;max-width:270px;color:var(--text-2)}\ntd.t-tf{min-width:140px;max-width:200px;color:var(--text-2)}\ntd.t-exp{min-width:130px;max-width:190px}\n.sbadge{display:inline-flex;align-items:center;gap:7px;white-space:nowrap}\n.sbadge i{width:8px;height:8px;border-radius:50%;display:inline-block;flex:0 0 auto}\n.tag{display:inline-block;font-size:10.5px;font-weight:700;letter-spacing:.03em;padding:2px 6px;border-radius:5px;background:var(--accent-soft);color:var(--accent-ink);margin-left:6px;vertical-align:1px;white-space:nowrap}\n.tag.chg{background:var(--warn-soft);color:var(--warn-ink)}\n.files{white-space:nowrap}\n.files a{display:inline-flex;font-size:12px;padding:2px 7px;border:1px solid var(--border-strong);border-radius:6px;color:var(--text);text-decoration:none;margin-right:4px}\n.files a:hover{background:var(--surface-2)}\n.muted{color:var(--text-3)}\n.empty{padding:44px 16px;text-align:center;color:var(--text-2)}\n\n/* Drawer */\n.backdrop{position:fixed;inset:0;background:rgba(0,0,0,.35);opacity:0;pointer-events:none;transition:opacity .2s;z-index:40}\n.backdrop.open{opacity:1;pointer-events:auto}\n.drawer{position:fixed;top:0;right:0;bottom:0;width:min(700px,100%);background:var(--surface);border-left:1px solid var(--border);box-shadow:-10px 0 36px rgba(0,0,0,.14);transform:translateX(102%);transition:transform .25s ease;z-index:41;display:flex;flex-direction:column;visibility:hidden}\n.drawer.open{transform:none;visibility:visible}\n.dhead{padding:18px 20px 14px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:flex-start}\n.dhead h2{font-size:17px;margin:8px 0 4px;line-height:1.35;font-weight:640}\n.dhead .di{color:var(--text-2);font-size:13.5px}\n.dbody{padding:16px 20px 36px;overflow-y:auto}\n.dmeta{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px 18px;margin-bottom:16px;padding:12px 14px;background:var(--surface-2);border-radius:10px}\n.dmeta span{display:block;font-size:11.5px;color:var(--text-3)}\n.dmeta b{font-weight:550;font-size:13.5px;word-break:break-word}\n.dact{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}\n.dsec{margin-bottom:18px}\n.dsec h3{font-size:11.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--text-2);margin:0 0 6px;font-weight:650}\n.dsec .tx{white-space:pre-wrap;word-break:break-word;font-size:13.5px;line-height:1.6}\n.iconbtn{width:34px;height:34px;flex:0 0 auto;border-radius:8px;border:1px solid var(--border-strong);background:var(--surface);color:var(--text);display:inline-flex;align-items:center;justify-content:center;cursor:pointer;margin-left:auto}\n.iconbtn:hover{background:var(--surface-2)}\n.iconbtn svg{width:18px;height:18px}\n\n/* Misc */\n#tip{position:fixed;left:0;top:0;z-index:60;pointer-events:none;background:var(--tip-bg);color:var(--tip-text);font-size:12px;line-height:1.4;padding:6px 9px;border-radius:7px;white-space:pre-line;opacity:0;max-width:300px;box-shadow:0 4px 14px rgba(0,0,0,.18)}\n#toast{position:fixed;left:50%;bottom:20px;transform:translate(-50%,16px);opacity:0;pointer-events:none;transition:all .22s ease;z-index:70;background:var(--tip-bg);color:var(--tip-text);padding:10px 16px;border-radius:10px;font-size:13.5px;max-width:calc(100% - 32px);box-shadow:0 6px 24px rgba(0,0,0,.2)}\n#toast.show{opacity:1;transform:translate(-50%,0)}\n#drop{position:fixed;inset:12px;border:2px dashed var(--accent);border-radius:16px;background:var(--accent-soft);backdrop-filter:blur(2px);display:none;align-items:center;justify-content:center;z-index:80;font-size:18px;font-weight:600;color:var(--accent-ink);text-align:center;padding:16px}\n#drop.show{display:flex}\n.foot{margin-top:22px;color:var(--text-3);font-size:12.5px}\n.foot summary{cursor:pointer;color:var(--text-2);font-weight:550;width:max-content;max-width:100%}\n.foot .src{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}\n.foot .src input{flex:1 1 360px;min-width:0}\n.foot p{margin:8px 0 0}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n</style>\n</head>\n<body>\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <symbol id=\"i-refresh\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12a9 9 0 1 1-2.64-6.36\"/><path d=\"M21 3v6h-6\"/></symbol>\n  <symbol id=\"i-upload\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 15V3\"/><path d=\"m7 8 5-5 5 5\"/><path d=\"M5 21h14\"/></symbol>\n  <symbol id=\"i-download\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v12\"/><path d=\"m7 10 5 5 5-5\"/><path d=\"M5 21h14\"/></symbol>\n  <symbol id=\"i-ext\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 4h6v6\"/><path d=\"M20 4 10 14\"/><path d=\"M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5\"/></symbol>\n  <symbol id=\"i-search\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.5-3.5\"/></symbol>\n  <symbol id=\"i-x\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></symbol>\n  <symbol id=\"i-alert\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6\"/><path d=\"M12 16.5v.5\"/></symbol>\n</svg>\n\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div>\n      <h1>Cereri de suport extern</h1>\n      <div class=\"meta\" id=\"meta\"><span class=\"live-dot\" id=\"liveDot\"></span><span id=\"metaText\">Se încarcă datele…</span></div>\n    </div>\n    <div class=\"actions\">\n      <label class=\"auto\" title=\"Reîncarcă automat datele de pe link\">Auto\n        <select class=\"ctl\" id=\"auto\" aria-label=\"Actualizare automată\">\n          <option value=\"0\">oprit</option>\n          <option value=\"1\">1 min</option>\n          <option value=\"5\">5 min</option>\n          <option value=\"15\">15 min</option>\n          <option value=\"30\">30 min</option>\n        </select>\n      </label>\n      <button class=\"btn\" id=\"btnFile\" type=\"button\" title=\"Încarcă un fișier CSV descărcat de pe link\"><svg><use href=\"#i-upload\"/></svg>Încarcă CSV</button>\n      <a class=\"btn\" id=\"btnLogout\" href=\"/logout\" hidden title=\"Ieși din cont pe acest dispozitiv\">Ieșire</a>\n      <button class=\"btn primary\" id=\"btnRestart\" type=\"button\" title=\"Reîncarcă datele actualizate de pe link\"><svg class=\"spin\"><use href=\"#i-refresh\"/></svg><span>Restart</span></button>\n      <input type=\"file\" id=\"fileInput\" accept=\".csv,text/csv\" hidden>\n    </div>\n  </header>\n\n  <div class=\"banner\" id=\"banner\" role=\"status\" aria-live=\"polite\"></div>\n\n  <section class=\"kpis\" id=\"kpis\" aria-label=\"Indicatori\"></section>\n\n  <section class=\"card filters\" aria-label=\"Filtre\">\n    <div class=\"search\">\n      <svg><use href=\"#i-search\"/></svg>\n      <input class=\"ctl\" id=\"q\" type=\"search\" placeholder=\"Caută în toate câmpurile (titlu, instituție, expert, text)…\" aria-label=\"Căutare\">\n    </div>\n    <div class=\"chips\" id=\"chips\" role=\"group\" aria-label=\"Filtru status\"></div>\n    <select class=\"ctl\" id=\"fInst\" aria-label=\"Filtru instituție\"></select>\n    <select class=\"ctl\" id=\"fMonth\" aria-label=\"Filtru lună\"></select>\n    <button class=\"linkbtn\" id=\"btnReset\" type=\"button\" hidden>Resetează filtrele</button>\n  </section>\n\n  <section class=\"charts\">\n    <div class=\"card panel c-status\">\n      <h2>Cereri după status</h2>\n      <div class=\"hint\">Click pe un status pentru a filtra</div>\n      <div id=\"statusBox\"></div>\n    </div>\n    <div class=\"card panel c-month\">\n      <h2>Cereri depuse pe lună</h2>\n      <div class=\"hint\">Click pe o lună pentru a filtra</div>\n      <div id=\"monthBox\"></div>\n    </div>\n    <div class=\"card panel c-inst\">\n      <h2>Cereri pe instituții</h2>\n      <div class=\"hint\">Click pe o instituție pentru a filtra</div>\n      <div id=\"instBox\"></div>\n    </div>\n  </section>\n\n  <section class=\"card\" aria-label=\"Lista cererilor\">\n    <div class=\"thead\">\n      <h2>Cereri<span class=\"cnt\" id=\"tCount\"></span></h2>\n      <button class=\"btn sm\" id=\"btnExport\" type=\"button\" title=\"Descarcă lista filtrată ca CSV\"><svg><use href=\"#i-download\"/></svg>Exportă CSV filtrat</button>\n    </div>\n    <div class=\"tscroll\" id=\"tableBox\"></div>\n  </section>\n\n  <footer class=\"foot\">\n    <details id=\"srcBox\">\n      <summary>Sursa datelor</summary>\n      <div class=\"src\">\n        <input class=\"ctl\" id=\"srcUrl\" type=\"url\" placeholder=\"https://oformo.com/api/export?…&amp;token=…\" aria-label=\"Link export CSV oformo\">\n        <button class=\"btn sm\" id=\"btnSrcSave\" type=\"button\">Salvează și reîncarcă</button>\n        <button class=\"btn sm\" id=\"btnSrcReset\" type=\"button\">Șterge link-ul</button>\n      </div>\n      <p>Link-ul de export conține un token de acces. Se păstrează doar în acest browser — nu-l pune în fișiere publice sau pe GitHub. Ultimele date încărcate rămân în browser, ca dashboard-ul să funcționeze și fără internet.</p>\n    </details>\n    <p id=\"serverNote\" hidden>Datele vin prin serverul securizat. Link-ul de export cu token-ul este păstrat doar pe server, ca secret.</p>\n  </footer>\n</div>\n\n<div class=\"backdrop\" id=\"backdrop\"></div>\n<aside class=\"drawer\" id=\"drawer\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"dTitle\"></aside>\n<div id=\"tip\" role=\"tooltip\"></div>\n<div id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"drop\">Eliberează fișierul CSV pentru a-l încărca în dashboard</div>\n\n<!--SERVER_CONFIG-->\n<script>\n(function(){\n'use strict';\n\n/* ---------- Configurare ---------- */\n// Mod server (Cloudflare Worker): serverul injectează window.DASHBOARD_SERVER și păstrează link-ul cu token ca secret.\nconst SERVER = (window.DASHBOARD_SERVER && typeof window.DASHBOARD_SERVER.dataPath === 'string') ? window.DASHBOARD_SERVER : null;\n// Mod local („Porneste dashboard.bat”): serverul PowerShell de pe localhost descarcă CSV-ul în locul browserului.\nconst VIA_LOCAL = !SERVER && /^https?:$/.test(location.protocol) && /^(localhost|127\\.0\\.0\\.1|\\[::1\\])$/.test(location.hostname);\n// Nu scrie token-ul în acest fișier: link-ul se introduce în „Sursa datelor” și rămâne doar în browser.\nconst DEFAULT_URL = '';\nconst LS = { url:'oformoDash.url', csv:'oformoDash.csv', csvTs:'oformoDash.csvTs', snap:'oformoDash.snapshot', auto:'oformoDash.auto' };\nconst store = {\n  get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } },\n  set(k,v){ try{ localStorage.setItem(k,v); return true; }catch(e){ return false; } },\n  del(k){ try{ localStorage.removeItem(k); }catch(e){} }\n};\n\nconst MONTHS = ['ian','feb','mar','apr','mai','iun','iul','aug','sep','oct','noi','dec'];\nconst MONTHS_LONG = ['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'];\nconst STATUS_RO = {'new':'Nou','in progress':'În lucru','completed':'Finalizat','postponed':'Amânat','rejected':'Respins','approved':'Aprobat','cancelled':'Anulat','canceled':'Anulat','on hold':'În așteptare','pending':'În așteptare','closed':'Închis','draft':'Ciornă','archived':'Arhivat'};\nconst STATUS_FIXED = {'new':0,'in progress':1,'completed':2,'postponed':3};\nconst SLOTS = ['--s1','--s2','--s3','--s4','--s5','--s6','--s7','--s8'];\n\n/* ---------- Stare ---------- */\nlet dataUrl = store.get(LS.url) || DEFAULT_URL;\nlet H = [], C = {}, R = [];\nlet statusInfo = new Map();          // sk -> {label, color, rank}\nlet loadedAt = null, loadedFrom = null, fileName = '';\nlet prevTs = null, newIds = new Set(), changedIds = new Map();\nlet busy = false, autoTimer = null, lastFocus = null, lastFailed = false;\nconst st = { q:'', statuses:new Set(), inst:'', month:'', onlyChg:false, sort:{key:'date', dir:-1} };\n\nconst $ = s => document.querySelector(s);\nconst nf = new Intl.NumberFormat('ro-RO');\nconst fmt = n => nf.format(n);\n\n/* ---------- Utilitare ---------- */\nfunction esc(s){ return String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])); }\nfunction safeUrl(u){ u = (u||'').trim(); return /^https?:\\/\\/[^\\s]+$/i.test(u) ? u : ''; }\nfunction isEmail(s){ return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test((s||'').trim()); }\nfunction norm(h){ return String(h||'').toLowerCase().replace(/ /g,' ').replace(/[:\\s]+/g,' ').trim(); }\nfunction pad(n){ return String(n).padStart(2,'0'); }\nfunction fmtDate(d){ return d ? `${pad(d.getDate())}.${pad(d.getMonth()+1)}.${d.getFullYear()}` : '—'; }\nfunction fmtDT(t){ if(!t) return '—'; const d = new Date(t); return `${fmtDate(d)}, ${pad(d.getHours())}:${pad(d.getMinutes())}`; }\nfunction monthLabel(mk, long){ const [y,m] = mk.split('-').map(Number); return (long ? MONTHS_LONG : MONTHS)[m-1] + ' ' + y; }\nfunction statusLabel(sk){ const i = statusInfo.get(sk); return i ? i.label : sk; }\nfunction statusColor(sk){ const i = statusInfo.get(sk); return i ? i.color : 'var(--neutral)'; }\n\nfunction parseCSV(text){\n  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);\n  const rows = []; let row = [], field = '', inQ = false;\n  for (let i = 0, n = text.length; i < n; i++){\n    const c = text[i];\n    if (inQ){\n      if (c === '\"'){\n        if (text[i+1] === '\"'){ field += '\"'; i++; } else inQ = false;\n      } else field += c;\n      continue;\n    }\n    if (c === '\"') inQ = true;\n    else if (c === ',') { row.push(field); field = ''; }\n    else if (c === '\\n') { row.push(field); rows.push(row); row = []; field = ''; }\n    else if (c !== '\\r') field += c;\n  }\n  if (field !== '' || row.length){ row.push(field); rows.push(row); }\n  return rows.filter(r => !(r.length === 1 && r[0].trim() === ''));\n}\n\nfunction toCSV(rows){\n  return rows.map(r => r.map(v => { v = v == null ? '' : String(v); return /[\",\\r\\n]/.test(v) ? '\"' + v.replace(/\"/g,'\"\"') + '\"' : v; }).join(',')).join('\\r\\n');\n}\n\nfunction parseDate(s){\n  s = (s||'').trim(); let m;\n  if ((m = s.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})(?:[ T](\\d{1,2}):(\\d{2})(?::(\\d{2}))?)?/))) return new Date(+m[1], m[2]-1, +m[3], +(m[4]||0), +(m[5]||0), +(m[6]||0));\n  if ((m = s.match(/^(\\d{1,2})[./](\\d{1,2})[./](\\d{4})(?:[ T](\\d{1,2}):(\\d{2}))?/))) return new Date(+m[3], m[2]-1, +m[1], +(m[4]||0), +(m[5]||0));\n  return null;\n}\n\nfunction mapCols(nh){\n  const f = p => nh.findIndex(p);\n  return {\n    date: f(h => h === 'date'),\n    datetime: f(h => h === 'date/time'),\n    status: f(h => h === 'status'),\n    id: f(h => h === 'id'),\n    link: f(h => h === 'link'),\n    visible: f(h => h === 'visible'),\n    reviews: f(h => h === 'reviews'),\n    source: f(h => h === 'source'),\n    parent: f(h => h === 'parent'),\n    inst: f(h => h.startsWith('applicant institution') || h === 'institution' || h.startsWith('instituția')),\n    title: f(h => h.startsWith('title of planned') || h === 'title'),\n    timeframe: f(h => h.startsWith('planned timeframe')),\n    days: f(h => h.startsWith('estimated number of days')),\n    expert: f(h => h === 'name/surname'),\n    expertContact: f(h => h.startsWith('phone number/')),\n    cv: f(h => h === 'cv'),\n    tor: f(h => h === 'tor'),\n    contact: f(h => h.startsWith('contact person'))\n  };\n}\n\nconst NO_EXPERT = /^(to be (identified|selected|defined|determined|confirmed|recruited)|tbd|tbc|n\\/?a|none|nu|-+|\\.+|pending)\\b/i;\n\n/* ---------- Ingestie date ---------- */\nfunction ingest(text, source, ts){\n  const rows = parseCSV(text);\n  if (!rows.length) throw new Error('Fișierul primit este gol.');\n  const head = rows[0].map(h => h.trim());\n  const nh = head.map(norm);\n  if (!nh.includes('status') && !nh.includes('id')) {\n    throw new Error('Răspunsul nu este un CSV cu structura așteptată (lipsesc coloanele „Status” / „ID”). Primele caractere: ' + text.slice(0,120));\n  }\n  const cols = mapCols(nh);\n  const g = (a,k) => { const i = cols[k]; return i >= 0 && i < a.length ? (a[i]||'').trim() : ''; };\n  const instNames = new Map();\n  const recs = rows.slice(1).map((a, i) => {\n    while (a.length < head.length) a.push('');\n    const dateStr = g(a,'date') || g(a,'datetime');\n    const d = parseDate(dateStr);\n    const instRaw = g(a,'inst').replace(/\\s+/g,' ').replace(/[\\s:;.,]+$/,'');\n    const instKey = instRaw.toLowerCase() || '—';\n    if (!instNames.has(instKey)) instNames.set(instKey, instRaw || '— (necompletat)');\n    const daysText = g(a,'days');\n    const dm = daysText.match(/\\d+(?:[.,]\\d+)?/);\n    let days = dm ? parseFloat(dm[0].replace(',','.')) : null;\n    if (days !== null && (days <= 0 || days > 2000)) days = null;\n    const expert = g(a,'expert');\n    const status = g(a,'status') || '—';\n    return {\n      i, a, id: g(a,'id') || ('rând-' + (i+1)), d, dateStr,\n      mk: d ? `${d.getFullYear()}-${pad(d.getMonth()+1)}` : '',\n      status, sk: status.toLowerCase(), instKey, inst: '',\n      title: g(a,'title') || '(fără titlu)', tf: g(a,'timeframe'),\n      daysText, days, expert, expertOk: !!expert && !NO_EXPERT.test(expert),\n      link: safeUrl(g(a,'link')), cv: safeUrl(g(a,'cv')), tor: safeUrl(g(a,'tor')),\n      reviews: parseInt(g(a,'reviews'),10) || 0,\n      search: a.join(' \\u0001 ').toLowerCase()\n    };\n  });\n  recs.forEach(r => r.inst = instNames.get(r.instKey));\n\n  // Statusuri: ordine fixă pentru cele cunoscute, restul după frecvență. Culoarea urmează statusul, nu rangul.\n  const counts = new Map(); const firstLabel = new Map();\n  recs.forEach(r => { counts.set(r.sk, (counts.get(r.sk)||0) + 1); if(!firstLabel.has(r.sk)) firstLabel.set(r.sk, r.status); });\n  const keys = [...counts.keys()].sort((x,y) => {\n    const ix = x in STATUS_FIXED ? STATUS_FIXED[x] : 99, iy = y in STATUS_FIXED ? STATUS_FIXED[y] : 99;\n    return ix - iy || counts.get(y) - counts.get(x) || x.localeCompare(y);\n  });\n  const info = new Map(); let next = 4;\n  keys.forEach((k, rank) => {\n    const color = k in STATUS_FIXED ? `var(${SLOTS[STATUS_FIXED[k]]})` : (next < 8 ? `var(${SLOTS[next++]})` : 'var(--neutral)');\n    info.set(k, { label: STATUS_RO[k] || firstLabel.get(k), raw: firstLabel.get(k), color, rank });\n  });\n\n  // Totul a reușit — aplicăm.\n  H = head; C = cols; R = recs; statusInfo = info;\n  loadedAt = ts ? new Date(ts) : new Date(); loadedFrom = source;\n\n  if (source !== 'cache'){\n    let prev = null; try { prev = JSON.parse(store.get(LS.snap) || 'null'); } catch(e) {}\n    newIds = new Set(); changedIds = new Map();\n    if (prev && prev.s){\n      R.forEach(r => {\n        if (!(r.id in prev.s)) newIds.add(r.id);\n        else if (prev.s[r.id] !== r.status) changedIds.set(r.id, prev.s[r.id]);\n      });\n      prevTs = prev.t;\n    } else prevTs = null;\n    store.set(LS.snap, JSON.stringify({ t: Date.now(), s: Object.fromEntries(R.map(r => [r.id, r.status])) }));\n  }\n\n  // Curățăm filtrele care nu mai au sens\n  [...st.statuses].forEach(s => { if (!statusInfo.has(s)) st.statuses.delete(s); });\n  if (st.inst && !R.some(r => r.instKey === st.inst)) st.inst = '';\n  if (st.month && !R.some(r => r.mk === st.month)) st.month = '';\n  if (st.onlyChg && !(newIds.size + changedIds.size)) st.onlyChg = false;\n\n  renderAll();\n}\n\n/* ---------- Încărcare de pe link ---------- */\nasync function refresh(){\n  if (busy) return;\n  busy = true; setBusy(true);\n  try {\n    let res;\n    if (SERVER){\n      res = await fetch(SERVER.dataPath, { cache:'no-store', credentials:'same-origin' });\n      if (res.status === 401){ location.href = SERVER.loginPath || '/'; return; }   // sesiunea a expirat\n    } else if (!dataUrl){\n      showNeedUrl(); return;\n    } else if (VIA_LOCAL){\n      // Deschis prin „Porneste dashboard.bat”: serverul local descarcă CSV-ul în locul browserului (fără CORS).\n      try { res = await fetch('/data.csv?url=' + encodeURIComponent(dataUrl), { cache:'no-store' }); }\n      catch(e){ const err = new Error('local'); err.local = true; throw err; }\n      if (res.status === 404) res = await fetch(dataUrl, { cache:'no-store', credentials:'omit' });\n    } else {\n      res = await fetch(dataUrl, { cache:'no-store', credentials:'omit' });\n    }\n    if (!res.ok){\n      let t = ''; try { t = (await res.text()).trim(); } catch(e) {}\n      const err = new Error(`Serverul a răspuns cu eroarea ${res.status}${t ? ' — ' + t.slice(0,160) : ''}`);\n      err.http = res.status; throw err;\n    }\n    const text = await res.text();\n    ingest(text, 'live');\n    cacheCSV(text);\n    lastFailed = false;\n    hideBanner();\n    let msg = `Date actualizate · ${fmt(R.length)} cereri`;\n    if (prevTs) msg += ` · ${newIds.size} ${newIds.size === 1 ? 'nouă' : 'noi'} · ${changedIds.size} cu status schimbat`;\n    toast(msg);\n  } catch(err) {\n    showError(err);\n  } finally {\n    busy = false; setBusy(false);\n  }\n}\n\nfunction setBusy(on){\n  const b = $('#btnRestart');\n  b.disabled = on; b.classList.toggle('loading', on);\n  b.querySelector('span').textContent = on ? 'Se încarcă…' : 'Restart';\n  if (on && !R.length) $('#metaText').textContent = 'Se încarcă datele de pe link…';\n  if (!on) renderMeta();\n}\n\nfunction showError(err){\n  lastFailed = true;\n  const network = err instanceof TypeError || /failed to fetch|networkerror|load failed/i.test(err.message||'');\n  let p;\n  if (SERVER) p = network ? 'Nu am primit răspuns de la server. Verifică conexiunea la internet.' : esc(err.message);\n  else if (err.local) p = 'Serverul local nu răspunde — probabil fereastra „Porneste dashboard” a fost închisă. Pornește din nou <b>Porneste dashboard.bat</b> și apasă Restart.';\n  else if (network && !VIA_LOCAL) p = 'Browserul nu permite unei pagini deschise direct ca fișier să citească datele de pe oformo.com (restricția CORS a site-ului). <b>Soluția:</b> închide această pagină și pornește dashboard-ul cu <b>Porneste dashboard.bat</b> din același folder — atunci Restart aduce datele automat.';\n  else if (network) p = 'Nu am primit răspuns de la oformo.com. Verifică conexiunea la internet.';\n  else if (err.http === 401 || err.http === 403) p = esc(err.message) + '. Token-ul din link poate fi expirat sau revocat — pune link-ul nou în „Sursa datelor” (jos de tot).';\n  else p = esc(err.message);\n  p += R.length ? ` Se afișează ultimele date disponibile (${esc(fmtDT(loadedAt))}).` : '';\n  if (!SERVER) p += ' Variantă manuală: descarcă CSV-ul de pe link și încarcă-l aici (sau trage fișierul peste pagină).';\n  const acts = [`<button class=\"btn sm primary\" type=\"button\" data-act=\"retry\"><svg><use href=\"#i-refresh\"/></svg>Încearcă din nou</button>`];\n  if (!SERVER && safeUrl(dataUrl)) acts.push(`<a class=\"btn sm\" href=\"${esc(dataUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\"><svg><use href=\"#i-download\"/></svg>Descarcă CSV de pe link</a>`);\n  if (!SERVER) acts.push(`<button class=\"btn sm\" type=\"button\" data-act=\"file\"><svg><use href=\"#i-upload\"/></svg>Încarcă fișierul descărcat</button>`);\n  showBanner('error', 'Nu am putut încărca datele', p, acts);\n}\n\nfunction showNeedUrl(){\n  showBanner('info', 'Adaugă link-ul de export oformo',\n    'Lipește link-ul de export CSV (cel cu <b>token=</b>) în „Sursa datelor”, jos în pagină. Se păstrează doar în acest browser, nu în fișier. Sau încarcă direct un fișier CSV descărcat.',\n    [`<button class=\"btn sm primary\" type=\"button\" data-act=\"src\">Deschide „Sursa datelor”</button>`,\n     `<button class=\"btn sm\" type=\"button\" data-act=\"file\"><svg><use href=\"#i-upload\"/></svg>Încarcă fișier CSV</button>`]);\n}\n\n// În modul server nu păstrăm datele (cu date personale) în browser; păstrăm doar instantaneul ID → status pentru „noi / modificate”.\nfunction cacheCSV(text){\n  if (SERVER) return;\n  store.set(LS.csv, text); store.set(LS.csvTs, String(Date.now()));\n}\n\nfunction showBanner(kind, title, html, actions){\n  const b = $('#banner');\n  b.className = 'banner show ' + kind;\n  b.innerHTML = `<svg class=\"ic\"><use href=\"#i-alert\"/></svg><div><b>${esc(title)}</b><p>${html}</p>${actions && actions.length ? `<div class=\"ba\">${actions.join('')}</div>` : ''}</div>`;\n}\nfunction hideBanner(){ const b = $('#banner'); b.className = 'banner'; b.innerHTML = ''; }\n\nlet toastT = null;\nfunction toast(msg){\n  const t = $('#toast'); t.textContent = msg; t.classList.add('show');\n  clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('show'), 3800);\n}\n\n/* ---------- Încărcare fișier ---------- */\nasync function loadFile(file){\n  if (!file) return;\n  try {\n    const text = await file.text();\n    fileName = file.name;\n    ingest(text, 'file');\n    lastFailed = false; renderMeta();\n    cacheCSV(text);\n    hideBanner();\n    toast(`Fișier încărcat · ${fmt(R.length)} cereri`);\n  } catch(err) {\n    showBanner('error', 'Fișierul nu a putut fi citit', esc(err.message), []);\n  }\n}\n\n/* ---------- Filtrare ---------- */\nfunction matches(r, except){\n  if (except !== 'status' && st.statuses.size && !st.statuses.has(r.sk)) return false;\n  if (except !== 'inst' && st.inst && r.instKey !== st.inst) return false;\n  if (except !== 'month' && st.month && r.mk !== st.month) return false;\n  if (st.onlyChg && !(newIds.has(r.id) || changedIds.has(r.id))) return false;\n  if (st.q){ const terms = st.q.toLowerCase().split(/\\s+/).filter(Boolean); for (const t of terms) if (!r.search.includes(t)) return false; }\n  return true;\n}\nconst filtered = except => R.filter(r => matches(r, except));\nconst anyFilter = () => !!(st.q || st.statuses.size || st.inst || st.month || st.onlyChg);\n\n/* ---------- Randare ---------- */\nfunction renderAll(){\n  renderMeta(); renderFilters(); renderKPIs(); renderStatus(); renderMonths(); renderInst(); renderTable();\n}\n\nfunction renderMeta(){\n  const dot = $('#liveDot');\n  dot.className = 'live-dot' + (loadedFrom === 'live' && !lastFailed ? ' live' : loadedFrom ? ' cache' : '');\n  if (!loadedAt){ $('#metaText').textContent = busy ? 'Se încarcă datele de pe link…' : 'Nu sunt date încărcate'; return; }\n  const src = loadedFrom === 'live' ? (SERVER ? 'actualizate prin server' : 'direct de pe link') : loadedFrom === 'file' ? `din fișierul „${fileName}”` : 'din memoria browserului (ultima încărcare)';\n  $('#metaText').textContent = `Date din ${fmtDT(loadedAt)} · ${src} · ${fmt(R.length)} cereri` + (lastFailed ? ' · ultima actualizare a eșuat' : '');\n}\n\nfunction renderFilters(){\n  const base = filtered('status');\n  const cnt = new Map(); base.forEach(r => cnt.set(r.sk, (cnt.get(r.sk)||0)+1));\n  $('#chips').innerHTML = [...statusInfo.entries()].map(([k,i]) =>\n    `<button class=\"chip\" type=\"button\" data-status=\"${esc(k)}\" aria-pressed=\"${st.statuses.has(k)}\"><span class=\"dot\" style=\"background:${i.color}\"></span>${esc(i.label)}<span class=\"n\">${fmt(cnt.get(k)||0)}</span></button>`\n  ).join('');\n\n  const ib = filtered('inst'); const ic = new Map(); ib.forEach(r => ic.set(r.instKey, (ic.get(r.instKey)||0)+1));\n  const insts = [...new Map(R.map(r => [r.instKey, r.inst])).entries()].sort((a,b) => a[1].localeCompare(b[1], 'ro'));\n  $('#fInst').innerHTML = `<option value=\"\">Toate instituțiile (${fmt(insts.length)})</option>` +\n    insts.map(([k,n]) => `<option value=\"${esc(k)}\">${esc(n)} (${fmt(ic.get(k)||0)})</option>`).join('');\n  $('#fInst').value = st.inst;\n\n  const months = [...new Set(R.map(r => r.mk).filter(Boolean))].sort().reverse();\n  $('#fMonth').innerHTML = `<option value=\"\">Toate lunile</option>` + months.map(m => `<option value=\"${m}\">${monthLabel(m, true)}</option>`).join('');\n  $('#fMonth').value = st.month;\n\n  $('#btnReset').hidden = !anyFilter();\n}\n\nfunction renderKPIs(){\n  if (!R.length){\n    $('#kpis').innerHTML = ['Cereri','Instituții solicitante','Experți identificați','Zile-expert estimate','Noi / modificate']\n      .map(l => `<div class=\"card kpi\"><div class=\"l\">${l}</div><div class=\"v\">—</div><div class=\"s\">&nbsp;</div></div>`).join('');\n    return;\n  }\n  const f = filtered();\n  const insts = new Set(f.map(r => r.instKey)).size;\n  const ex = f.filter(r => r.expertOk).length;\n  const wd = f.filter(r => r.days != null); const sumDays = wd.reduce((s,r) => s + r.days, 0);\n  const chg = newIds.size + changedIds.size;\n  const pct = f.length ? Math.round(ex / f.length * 100) : 0;\n  const tiles = [\n    { l:'Cereri', v:fmt(f.length), s: anyFilter() ? `din ${fmt(R.length)} în total` : 'toate cererile din formular' },\n    { l:'Instituții solicitante', v:fmt(insts), s: 'instituții distincte' },\n    { l:'Experți identificați', v:fmt(ex), s:`din ${fmt(f.length)} cereri · ${pct}%` },\n    { l:'Zile-expert estimate', v:fmt(Math.round(sumDays)), s:`din ${fmt(wd.length)} cereri cu număr de zile` },\n  ];\n  let h = tiles.map(t => `<div class=\"card kpi\"><div class=\"l\">${t.l}</div><div class=\"v\">${t.v}</div><div class=\"s\">${esc(t.s)}</div></div>`).join('');\n  if (prevTs){\n    const sub = `${newIds.size} ${newIds.size === 1 ? 'nouă' : 'noi'} · ${changedIds.size} status schimbat — față de ${fmtDT(prevTs)}`;\n    h += chg\n      ? `<button class=\"card kpi${st.onlyChg ? ' active' : ''}\" type=\"button\" data-act=\"onlychg\" aria-pressed=\"${st.onlyChg}\" title=\"Arată doar cererile noi sau cu status schimbat\"><div class=\"l\">Noi / modificate ${st.onlyChg ? '· filtru activ' : '· click pentru filtru'}</div><div class=\"v\">${fmt(chg)}</div><div class=\"s\">${esc(sub)}</div></button>`\n      : `<div class=\"card kpi\"><div class=\"l\">Noi / modificate</div><div class=\"v\">0</div><div class=\"s\">${esc(sub)}</div></div>`;\n  } else {\n    h += `<div class=\"card kpi\"><div class=\"l\">Noi / modificate</div><div class=\"v\">—</div><div class=\"s\">apar după următorul Restart</div></div>`;\n  }\n  $('#kpis').innerHTML = h;\n}\n\nfunction renderStatus(){\n  const box = $('#statusBox');\n  const f = filtered('status');\n  if (!f.length){ box.innerHTML = `<div class=\"nodata\">${R.length ? 'Nicio cerere pentru filtrele alese' : 'Nu există date încă'}</div>`; return; }\n  const cnt = new Map(); f.forEach(r => cnt.set(r.sk, (cnt.get(r.sk)||0)+1));\n  const keys = [...statusInfo.keys()].filter(k => cnt.get(k) || st.statuses.has(k));\n  const sel = st.statuses.size > 0;\n  const seg = keys.filter(k => cnt.get(k)).map(k => {\n    const n = cnt.get(k), p = Math.round(n / f.length * 100);\n    return `<span data-status=\"${esc(k)}\" class=\"${sel && !st.statuses.has(k) ? 'dim' : ''}\" style=\"flex:${n} 1 0;background:${statusColor(k)}\" data-tip=\"${esc(statusLabel(k))}\\n${fmt(n)} cereri · ${p}%\"></span>`;\n  }).join('');\n  const rows = keys.map(k => {\n    const n = cnt.get(k) || 0, p = f.length ? Math.round(n / f.length * 100) : 0, on = st.statuses.has(k);\n    const raw = statusInfo.get(k).raw;\n    return `<button class=\"srow${on ? ' sel' : ''}${sel && !on ? ' dim' : ''}\" type=\"button\" data-status=\"${esc(k)}\" aria-pressed=\"${on}\" title=\"${esc(raw)}\"><span class=\"sw\" style=\"background:${statusColor(k)}\"></span><span class=\"nm\">${esc(statusLabel(k))}</span><span class=\"cnt\">${fmt(n)}</span><span class=\"pct\">${p}%</span></button>`;\n  }).join('');\n  box.innerHTML = `<div class=\"seg\" role=\"img\" aria-label=\"Distribuția cererilor pe statusuri\">${seg}</div>${rows}`;\n}\n\nfunction niceMax(v){\n  if (v <= 2) return 2;\n  if (v <= 10) return Math.ceil(v/2)*2;\n  const e = Math.pow(10, Math.floor(Math.log10(v))), f = v / e;\n  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * e;\n}\n\nfunction renderMonths(){\n  const box = $('#monthBox');\n  const f = filtered('month').filter(r => r.mk);\n  if (!f.length){ box.innerHTML = `<div class=\"nodata\">${R.length ? 'Nicio cerere pentru filtrele alese' : 'Nu există date încă'}</div>`; return; }\n  const cnt = new Map(); f.forEach(r => cnt.set(r.mk, (cnt.get(r.mk)||0)+1));\n  const ks = [...cnt.keys()].sort();\n  if (st.month){ if (st.month < ks[0]) ks.unshift(st.month); if (st.month > ks[ks.length-1]) ks.push(st.month); }\n  let [y, m] = ks[0].split('-').map(Number); const [ly, lm] = ks[ks.length-1].split('-').map(Number);\n  const months = [];\n  while (y < ly || (y === ly && m <= lm)){ months.push(`${y}-${pad(m)}`); m++; if (m > 12){ m = 1; y++; } }\n  const vals = months.map(k => cnt.get(k) || 0);\n  const max = Math.max(...vals), top = niceMax(max);\n  const maxIdx = vals.indexOf(max), lastIdx = vals.length - 1;\n  const stride = Math.ceil(months.length / 12);\n  const sel = !!st.month;\n  const grid = [top, top/2, 0].map((v,i) => `<div class=\"${i === 2 ? 'base' : ''}\" style=\"bottom:${v/top*100}%\"><span>${fmt(v)}</span></div>`).join('');\n  const cols = months.map((k,i) => {\n    const v = vals[i], on = st.month === k;\n    const showVal = v > 0 && (i === maxIdx || i === lastIdx || on);\n    return `<button class=\"cc-col${sel && !on ? ' dim' : ''}\" type=\"button\" data-month=\"${k}\" aria-pressed=\"${on}\" aria-label=\"${monthLabel(k,true)}: ${v} cereri\" data-tip=\"${monthLabel(k,true)}\\n${fmt(v)} ${v === 1 ? 'cerere' : 'cereri'}\">${showVal ? `<span class=\"cc-val\">${fmt(v)}</span>` : ''}<span class=\"cc-bar\" style=\"height:${v ? Math.max(v/top*100, 1.2) : 0}%\"></span></button>`;\n  }).join('');\n  const xl = months.map((k,i) => {\n    const [yy, mm] = k.split('-').map(Number);\n    const show = i % stride === 0 || i === lastIdx;\n    const yr = (i === 0 || mm === 1) ? `<br>${yy}` : '<br>&nbsp;';\n    return `<span>${show ? MONTHS[mm-1] + yr : '&nbsp;<br>&nbsp;'}</span>`;\n  }).join('');\n  box.innerHTML = `<div class=\"cc-plot\"><div class=\"cc-grid\">${grid}</div><div class=\"cc-cols\">${cols}</div></div><div class=\"cc-x\" aria-hidden=\"true\">${xl}</div>`;\n}\n\nfunction renderInst(){\n  const box = $('#instBox');\n  const f = filtered('inst');\n  if (!f.length){ box.innerHTML = `<div class=\"nodata\">${R.length ? 'Nicio cerere pentru filtrele alese' : 'Nu există date încă'}</div>`; return; }\n  const cnt = new Map(); f.forEach(r => cnt.set(r.instKey, (cnt.get(r.instKey)||0)+1));\n  if (st.inst && !cnt.has(st.inst)) cnt.set(st.inst, 0);\n  const names = new Map(R.map(r => [r.instKey, r.inst]));\n  const list = [...cnt.entries()].sort((a,b) => b[1] - a[1] || names.get(a[0]).localeCompare(names.get(b[0]), 'ro'));\n  const max = Math.max(...list.map(x => x[1]), 1);\n  const sel = !!st.inst;\n  box.innerHTML = `<div class=\"ilist\">` + list.map(([k,n]) => {\n    const on = st.inst === k, nm = names.get(k);\n    return `<button class=\"irow${on ? ' sel' : ''}${sel && !on ? ' dim' : ''}\" type=\"button\" data-inst=\"${esc(k)}\" aria-pressed=\"${on}\" data-tip=\"${esc(nm)}\\n${fmt(n)} ${n === 1 ? 'cerere' : 'cereri'}\"><span class=\"nm\">${esc(nm)}</span><span class=\"tr\"><span class=\"b\" style=\"width:${n ? n/max*100 : 0}%\"></span></span><span class=\"c\">${fmt(n)}</span></button>`;\n  }).join('') + `</div>`;\n}\n\nconst TCOLS = [\n  { key:'date',     label:'Data',              sort: r => r.d ? r.d.getTime() : 0 },\n  { key:'title',    label:'Titlul suportului', sort: r => r.title.toLowerCase() },\n  { key:'inst',     label:'Instituția',        sort: r => r.inst.toLowerCase() },\n  { key:'status',   label:'Status',            sort: r => (statusInfo.get(r.sk)||{rank:99}).rank },\n  { key:'tf',       label:'Perioada',          sort: r => r.tf.toLowerCase() },\n  { key:'days',     label:'Zile',              sort: r => r.days == null ? -1 : r.days, num:true },\n  { key:'expert',   label:'Expert',            sort: r => r.expertOk ? r.expert.toLowerCase() : '￿' },\n  { key:'files',    label:'Fișiere',           sort: r => (r.tor ? 2 : 0) + (r.cv ? 1 : 0) },\n  { key:'reviews',  label:'Recenzii',          sort: r => r.reviews, num:true }\n];\n\nfunction renderTable(){\n  const box = $('#tableBox');\n  if (!R.length){\n    $('#tCount').textContent = '';\n    box.innerHTML = `<div class=\"empty\">${busy ? 'Se încarcă datele…' : 'Nu sunt date încă. Apasă <b>Restart</b> sau încarcă fișierul CSV descărcat de pe link.'}</div>`;\n    return;\n  }\n  const col = TCOLS.find(c => c.key === st.sort.key) || TCOLS[0];\n  const dir = st.sort.dir;\n  const f = filtered().slice().sort((a,b) => {\n    const x = col.sort(a), y = col.sort(b);\n    const c = x < y ? -1 : x > y ? 1 : 0;\n    return c * dir || ((b.d ? b.d.getTime() : 0) - (a.d ? a.d.getTime() : 0));\n  });\n  $('#tCount').textContent = `· ${fmt(f.length)}${f.length !== R.length ? ' din ' + fmt(R.length) : ''}`;\n  if (!f.length){\n    box.innerHTML = `<div class=\"empty\">Nicio cerere nu corespunde filtrelor. <button class=\"linkbtn\" type=\"button\" data-act=\"reset\">Resetează filtrele</button></div>`;\n    return;\n  }\n  const th = TCOLS.map(c => {\n    const on = st.sort.key === c.key;\n    const ar = on ? (st.sort.dir === 1 ? '▲' : '▼') : '↕';\n    return `<th class=\"${c.num ? 'num' : ''}\" aria-sort=\"${on ? (st.sort.dir === 1 ? 'ascending' : 'descending') : 'none'}\"><button type=\"button\" data-sort=\"${c.key}\">${c.label}<span class=\"ar\">${ar}</span></button></th>`;\n  }).join('');\n  const tr = f.map(r => {\n    const isNew = newIds.has(r.id), chg = changedIds.get(r.id);\n    const tags = (isNew ? `<span class=\"tag\">NOU</span>` : '') + (chg != null ? `<span class=\"tag chg\" title=\"Status anterior: ${esc(chg)}\">STATUS SCHIMBAT</span>` : '');\n    const files = (r.tor ? `<a href=\"${esc(r.tor)}\" target=\"_blank\" rel=\"noopener noreferrer\" data-stop>ToR</a>` : '') + (r.cv ? `<a href=\"${esc(r.cv)}\" target=\"_blank\" rel=\"noopener noreferrer\" data-stop>CV</a>` : '');\n    return `<tr data-i=\"${r.i}\" tabindex=\"0\">\n      <td class=\"t-date\" title=\"${esc(r.dateStr)}\">${fmtDate(r.d)}</td>\n      <td class=\"t-title\"><span class=\"clamp\">${esc(r.title)}${tags}</span></td>\n      <td class=\"t-inst\"><span class=\"clamp\">${esc(r.inst)}</span></td>\n      <td><span class=\"sbadge\"><i style=\"background:${statusColor(r.sk)}\"></i>${esc(statusLabel(r.sk))}</span></td>\n      <td class=\"t-tf\"><span class=\"clamp\">${esc(r.tf) || '<span class=\"muted\">—</span>'}</span></td>\n      <td class=\"num\" title=\"${esc(r.daysText)}\">${r.days != null ? fmt(r.days) : '<span class=\"muted\">—</span>'}</td>\n      <td class=\"t-exp\"><span class=\"clamp\">${r.expertOk ? esc(r.expert) : `<span class=\"muted\">${esc(r.expert) || '—'}</span>`}</span></td>\n      <td class=\"files\">${files || '<span class=\"muted\">—</span>'}</td>\n      <td class=\"num\">${fmt(r.reviews)}</td>\n    </tr>`;\n  }).join('');\n  box.innerHTML = `<table><thead><tr>${th}</tr></thead><tbody>${tr}</tbody></table>`;\n}\n\n/* ---------- Detalii cerere ---------- */\nfunction valueHtml(v){\n  const u = safeUrl(v);\n  if (u) return `<a href=\"${esc(u)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(decodeURIComponent(u.split('/').pop() || u))}</a>`;\n  if (isEmail(v)) return `<a href=\"mailto:${esc(v.trim())}\">${esc(v)}</a>`;\n  return esc(v);\n}\n\nfunction openDrawer(i){\n  const r = R[i]; if (!r) return;\n  lastFocus = document.activeElement;\n  const used = new Set(['date','status','id','link','visible','reviews','source','parent','inst','title','timeframe','days','cv','tor'].map(k => C[k]).filter(x => x >= 0));\n  if (C.datetime >= 0 && (r.a[C.datetime]||'').trim() === r.dateStr) used.add(C.datetime);\n  const get = k => C[k] >= 0 ? (r.a[C[k]]||'').trim() : '';\n  const meta = [\n    ['Data depunerii', r.d ? fmtDT(r.d) : (r.dateStr || '—')],\n    ['Perioada planificată', r.tf || '—'],\n    ['Zile estimate', r.daysText || '—'],\n    ['Recenzii', String(r.reviews)],\n    ['Sursa', get('source') || '—'],\n    ['Vizibil', get('visible') || '—'],\n    ['ID', r.id]\n  ];\n  if (get('parent')) meta.push(['Părinte', get('parent')]);\n  const chg = changedIds.get(r.id);\n  const tags = (newIds.has(r.id) ? `<span class=\"tag\">NOU</span>` : '') + (chg != null ? `<span class=\"tag chg\">STATUS SCHIMBAT · era „${esc(chg)}”</span>` : '');\n  const actions = [\n    r.link ? `<a class=\"btn sm primary\" href=\"${esc(r.link)}\" target=\"_blank\" rel=\"noopener noreferrer\"><svg><use href=\"#i-ext\"/></svg>Deschide în oformo</a>` : '',\n    r.tor ? `<a class=\"btn sm\" href=\"${esc(r.tor)}\" target=\"_blank\" rel=\"noopener noreferrer\"><svg><use href=\"#i-download\"/></svg>ToR</a>` : '',\n    r.cv ? `<a class=\"btn sm\" href=\"${esc(r.cv)}\" target=\"_blank\" rel=\"noopener noreferrer\"><svg><use href=\"#i-download\"/></svg>CV expert</a>` : ''\n  ].join('');\n  const secs = H.map((h, j) => {\n    if (used.has(j)) return '';\n    const v = (r.a[j]||'').trim(); if (!v) return '';\n    return `<div class=\"dsec\"><h3>${esc(h.replace(/[:\\s]+$/,''))}</h3><div class=\"tx\">${valueHtml(v)}</div></div>`;\n  }).join('');\n  $('#drawer').innerHTML = `\n    <div class=\"dhead\">\n      <div style=\"min-width:0\">\n        <span class=\"sbadge\"><i style=\"background:${statusColor(r.sk)}\"></i>${esc(statusLabel(r.sk))}</span>${tags}\n        <h2 id=\"dTitle\">${esc(r.title)}</h2>\n        <div class=\"di\">${esc(r.inst)}</div>\n      </div>\n      <button class=\"iconbtn\" type=\"button\" data-act=\"close\" aria-label=\"Închide\"><svg><use href=\"#i-x\"/></svg></button>\n    </div>\n    <div class=\"dbody\">\n      <div class=\"dmeta\">${meta.map(([l,v]) => `<div><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}</div>\n      ${actions ? `<div class=\"dact\">${actions}</div>` : ''}\n      ${secs || '<p class=\"muted\">Nu există alte câmpuri completate.</p>'}\n    </div>`;\n  $('#drawer').classList.add('open'); $('#backdrop').classList.add('open');\n  $('#drawer').querySelector('.dbody').scrollTop = 0;\n  $('#drawer').querySelector('[data-act=\"close\"]').focus();\n}\nfunction closeDrawer(){\n  if (!$('#drawer').classList.contains('open')) return;\n  $('#drawer').classList.remove('open'); $('#backdrop').classList.remove('open');\n  if (lastFocus && lastFocus.focus) lastFocus.focus();\n}\n\n/* ---------- Export ---------- */\nfunction exportCSV(){\n  if (!R.length) return;\n  const f = filtered();\n  const blob = new Blob(['﻿' + toCSV([H, ...f.map(r => r.a)])], { type:'text/csv;charset=utf-8' });\n  const a = document.createElement('a');\n  const d = new Date();\n  a.href = URL.createObjectURL(blob);\n  a.download = `cereri_${anyFilter() ? 'filtrate_' : ''}${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}.csv`;\n  document.body.appendChild(a); a.click(); a.remove();\n  setTimeout(() => URL.revokeObjectURL(a.href), 2000);\n}\n\n/* ---------- Auto-refresh ---------- */\nfunction setupAuto(){\n  clearInterval(autoTimer); autoTimer = null;\n  const m = +$('#auto').value;\n  store.set(LS.auto, String(m));\n  if (m > 0) autoTimer = setInterval(refresh, m * 60000);\n}\n\n/* ---------- Evenimente ---------- */\nfunction resetFilters(){\n  st.q = ''; $('#q').value = ''; st.statuses.clear(); st.inst = ''; st.month = ''; st.onlyChg = false;\n  renderAll();\n}\n\ndocument.addEventListener('click', e => {\n  const t = e.target;\n  if (t.closest('[data-stop]')) return;\n  const act = t.closest('[data-act]');\n  if (act){\n    const a = act.dataset.act;\n    if (a === 'retry') refresh();\n    else if (a === 'file') $('#fileInput').click();\n    else if (a === 'src'){ const d = $('#srcBox'); d.open = true; d.scrollIntoView({ behavior:'smooth', block:'center' }); setTimeout(() => $('#srcUrl').focus(), 300); }\n    else if (a === 'close') closeDrawer();\n    else if (a === 'reset') resetFilters();\n    else if (a === 'onlychg'){ st.onlyChg = !st.onlyChg; renderAll(); }\n    return;\n  }\n  const s = t.closest('[data-status]');\n  if (s){ const k = s.dataset.status; st.statuses.has(k) ? st.statuses.delete(k) : st.statuses.add(k); renderAll(); return; }\n  const mo = t.closest('[data-month]');\n  if (mo){ st.month = st.month === mo.dataset.month ? '' : mo.dataset.month; renderAll(); return; }\n  const ins = t.closest('[data-inst]');\n  if (ins){ st.inst = st.inst === ins.dataset.inst ? '' : ins.dataset.inst; renderAll(); return; }\n  const so = t.closest('[data-sort]');\n  if (so){\n    const k = so.dataset.sort;\n    if (st.sort.key === k) st.sort.dir *= -1; else st.sort = { key:k, dir: (k === 'date' || k === 'days' || k === 'reviews') ? -1 : 1 };\n    renderTable(); return;\n  }\n  const row = t.closest('tbody tr[data-i]');\n  if (row){ openDrawer(+row.dataset.i); return; }\n});\ndocument.addEventListener('keydown', e => {\n  if (e.key === 'Escape') closeDrawer();\n  if (e.key === 'Enter' && e.target.matches && e.target.matches('tbody tr[data-i]')) openDrawer(+e.target.dataset.i);\n});\n$('#backdrop').addEventListener('click', closeDrawer);\n$('#btnRestart').addEventListener('click', refresh);\n$('#btnFile').addEventListener('click', () => $('#fileInput').click());\n$('#fileInput').addEventListener('change', e => { loadFile(e.target.files[0]); e.target.value = ''; });\n$('#btnExport').addEventListener('click', exportCSV);\n$('#btnReset').addEventListener('click', resetFilters);\n$('#fInst').addEventListener('change', e => { st.inst = e.target.value; renderAll(); });\n$('#fMonth').addEventListener('change', e => { st.month = e.target.value; renderAll(); });\nlet qT = null;\n$('#q').addEventListener('input', e => { clearTimeout(qT); qT = setTimeout(() => { st.q = e.target.value.trim(); renderAll(); }, 160); });\n$('#auto').addEventListener('change', setupAuto);\n\n$('#srcUrl').value = dataUrl;\n$('#btnSrcSave').addEventListener('click', () => {\n  const v = $('#srcUrl').value.trim();\n  if (!/^https:\\/\\//i.test(v)){ toast('Introdu un link valid care începe cu https://'); return; }\n  dataUrl = v; store.set(LS.url, v); refresh();\n});\n$('#btnSrcReset').addEventListener('click', () => { dataUrl = DEFAULT_URL; store.del(LS.url); $('#srcUrl').value = dataUrl; toast('Link-ul a fost șters din acest browser'); });\n\n// Tooltip\nconst tip = $('#tip');\nfunction placeTip(e){\n  const w = tip.offsetWidth, h = tip.offsetHeight;\n  let x = e.clientX + 14, y = e.clientY + 16;\n  if (x + w > innerWidth - 8) x = e.clientX - w - 14;\n  if (y + h > innerHeight - 8) y = e.clientY - h - 12;\n  tip.style.transform = `translate(${Math.max(8,x)}px,${Math.max(8,y)}px)`;\n}\ndocument.addEventListener('mouseover', e => {\n  const el = e.target.closest && e.target.closest('[data-tip]');\n  if (!el){ tip.style.opacity = 0; return; }\n  tip.textContent = el.dataset.tip; tip.style.opacity = 1; placeTip(e);\n});\ndocument.addEventListener('mousemove', e => { if (tip.style.opacity === '1') placeTip(e); });\naddEventListener('scroll', () => { tip.style.opacity = 0; }, { passive:true });\n\n// Drag & drop\nlet dragDepth = 0;\nconst hasFiles = e => e.dataTransfer && [...e.dataTransfer.types].includes('Files');\naddEventListener('dragenter', e => { if (!hasFiles(e)) return; e.preventDefault(); dragDepth++; $('#drop').classList.add('show'); });\naddEventListener('dragover', e => { if (hasFiles(e)) e.preventDefault(); });\naddEventListener('dragleave', () => { dragDepth = Math.max(0, dragDepth-1); if (!dragDepth) $('#drop').classList.remove('show'); });\naddEventListener('drop', e => { if (!hasFiles(e)) return; e.preventDefault(); dragDepth = 0; $('#drop').classList.remove('show'); loadFile(e.dataTransfer.files[0]); });\n\n/* ---------- Pornire ---------- */\nconst savedAuto = store.get(LS.auto);\nif (savedAuto && [...$('#auto').options].some(o => o.value === savedAuto)) $('#auto').value = savedAuto;\nsetupAuto();\nif (SERVER){\n  $('#srcBox').hidden = true; $('#serverNote').hidden = false; $('#btnLogout').hidden = false;\n  if (SERVER.logoutPath) $('#btnLogout').href = SERVER.logoutPath;\n  $('#btnFile').hidden = true;\n  store.del(LS.csv); store.del(LS.csvTs);\n} else {\n  const cached = store.get(LS.csv);\n  if (cached){ try { ingest(cached, 'cache', +store.get(LS.csvTs) || null); } catch(e){ store.del(LS.csv); } }\n}\nrenderAll();\nrefresh();\n})();\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (!env.OFORMO_URL || !env.DASHBOARD_PASSWORD) {
      return page(500, setupMissingPage(env));
    }
    if (String(env.DASHBOARD_PASSWORD).length < 8) {
      return page(500, messagePage('Parola este prea scurtă', 'Secretul DASHBOARD_PASSWORD trebuie să aibă cel puțin 8 caractere (recomandat 12+). Schimbă-l în Cloudflare → Settings → Variables and Secrets.'));
    }

    if (path === '/login') {
      if (request.method !== 'POST') return redirect('/');
      const form = await request.formData().catch(() => null);
      const given = form ? String(form.get('password') || '') : '';
      if (await safeEqual(given, String(env.DASHBOARD_PASSWORD))) {
        const exp = Date.now() + SESSION_DAYS * 864e5;
        const token = `${exp}.${await sign(String(exp), env.DASHBOARD_PASSWORD)}`;
        return redirect('/', { 'Set-Cookie': `${COOKIE}=${token}; Path=/; Max-Age=${SESSION_DAYS * 86400}; HttpOnly; Secure; SameSite=Lax` });
      }
      await new Promise(r => setTimeout(r, 1200)); // frânează încercările de ghicire a parolei
      return page(401, loginPage('Parola nu este corectă.'));
    }

    if (path === '/logout') {
      return redirect('/', { 'Set-Cookie': `${COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax` });
    }

    const authed = await checkSession(request, env.DASHBOARD_PASSWORD);

    if (path === '/data.csv') {
      if (!authed) return text(401, 'Sesiunea a expirat. Reîncarcă pagina și autentifică-te din nou.');
      let res;
      try {
        res = await fetch(env.OFORMO_URL, { headers: { 'User-Agent': 'cereri-dashboard-worker/1.0' }, cf: { cacheTtl: 0, cacheEverything: false } });
      } catch (e) {
        return text(502, 'Serverul nu a putut contacta oformo.com. Încearcă din nou peste câteva momente.');
      }
      if (!res.ok) {
        const hint = (res.status === 401 || res.status === 403)
          ? ' Token-ul din secretul OFORMO_URL poate fi expirat sau revocat — actualizează-l în Cloudflare.'
          : '';
        return text(502, `oformo.com a răspuns cu eroarea ${res.status}.${hint}`);
      }
      return new Response(res.body, {
        status: 200,
        headers: { ...securityHeaders(), 'Content-Type': 'text/csv; charset=utf-8', 'Cache-Control': 'no-store' }
      });
    }

    if (path === '/' || path === '/index.html') {
      if (!authed) return page(200, loginPage(''));
      const config = '<script>window.DASHBOARD_SERVER={dataPath:"/data.csv",logoutPath:"/logout",loginPath:"/"};</script>';
      return page(200, DASHBOARD_HTML.replace('<!--SERVER_CONFIG-->', config));
    }

    if (path === '/favicon.ico') return new Response(null, { status: 204 });
    return text(404, 'Pagina nu există.');
  }
};

/* ---------- Sesiune: cookie semnat HMAC cu parola (schimbarea parolei deconectează pe toată lumea) ---------- */

async function hmacKey(secret) {
  return crypto.subtle.importKey('raw', new TextEncoder().encode('cereri-dashboard|' + secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify']);
}

function b64url(buf) {
  let s = ''; const b = new Uint8Array(buf);
  for (let i = 0; i < b.length; i++) s += String.fromCharCode(b[i]);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromB64url(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  const bin = atob(s); const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function sign(data, secret) {
  const key = await hmacKey(secret);
  return b64url(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(data)));
}

async function checkSession(request, secret) {
  const cookie = request.headers.get('Cookie') || '';
  const m = cookie.match(new RegExp('(?:^|;\\s*)' + COOKIE + '=([^;]+)'));
  if (!m) return false;
  const [exp, sig] = m[1].split('.');
  if (!exp || !sig || !/^\d+$/.test(exp) || Number(exp) < Date.now()) return false;
  try {
    const key = await hmacKey(secret);
    return await crypto.subtle.verify('HMAC', key, fromB64url(sig), new TextEncoder().encode(exp));
  } catch (e) {
    return false;
  }
}

async function safeEqual(a, b) {
  const [ha, hb] = await Promise.all([a, b].map(s => crypto.subtle.digest('SHA-256', new TextEncoder().encode(s))));
  const x = new Uint8Array(ha), y = new Uint8Array(hb);
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}

/* ---------- Răspunsuri ---------- */

function securityHeaders() {
  return {
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY',
    'Referrer-Policy': 'no-referrer',
    'X-Robots-Tag': 'noindex, nofollow',
    'Content-Security-Policy': "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"
  };
}

function page(status, html) {
  return new Response(html, { status, headers: { ...securityHeaders(), 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}

function text(status, body) {
  return new Response(body, { status, headers: { ...securityHeaders(), 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' } });
}

function redirect(to, extra) {
  return new Response(null, { status: 303, headers: { ...securityHeaders(), Location: to, 'Cache-Control': 'no-store', ...(extra || {}) } });
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

const SHELL_CSS = `
:root{color-scheme:light;--bg:#f4f3f0;--surface:#fcfcfb;--border:#e4e3de;--border-strong:#cfcec8;--text:#0b0b0b;--text-2:#52514e;--accent:#2a78d6;--err:#a32626;--err-bg:#fdeeee}
@media (prefers-color-scheme: dark){:root{color-scheme:dark;--bg:#121211;--surface:#1a1a19;--border:#2c2c2a;--border-strong:#3e3e3b;--text:#f0efec;--text-2:#c3c2b7;--accent:#3987e5;--err:#f19a9a;--err-bg:#2a1717}}
*{box-sizing:border-box}html,body{margin:0;height:100%}
body{background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;display:flex;align-items:center;justify-content:center;padding:24px 16px}
.box{width:100%;max-width:380px;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px 24px;box-shadow:0 6px 24px rgba(0,0,0,.05)}
h1{font-size:20px;margin:0 0 6px;font-weight:650;letter-spacing:-.01em}
p{margin:0 0 18px;color:var(--text-2);font-size:14px}
label{display:block;font-size:13px;font-weight:600;margin-bottom:6px}
input{width:100%;height:42px;border:1px solid var(--border-strong);border-radius:9px;background:var(--surface);color:var(--text);padding:0 12px;font:inherit}
input:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
button{margin-top:14px;width:100%;height:42px;border:0;border-radius:9px;background:var(--accent);color:#fff;font:inherit;font-weight:600;cursor:pointer}
button:hover{filter:brightness(1.07)}
.err{background:var(--err-bg);color:var(--err);border-radius:8px;padding:9px 12px;font-size:13.5px;margin-bottom:14px}
code{font-size:13px;background:var(--bg);padding:1px 5px;border-radius:5px}
ul{margin:0;padding-left:18px;color:var(--text-2);font-size:14px}`;

function shell(title, body) {
  return `<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${SHELL_CSS}</style></head><body>${body}</body></html>`;
}

function loginPage(error) {
  return shell('Autentificare — Cereri de suport', `
<form class="box" method="post" action="/login">
  <h1>Cereri de suport extern</h1>
  <p>Introdu parola pentru a deschide dashboard-ul.</p>
  ${error ? `<div class="err" role="alert">${esc(error)}</div>` : ''}
  <label for="password">Parola</label>
  <input id="password" name="password" type="password" autocomplete="current-password" required autofocus>
  <button type="submit">Intră</button>
</form>`);
}

function messagePage(title, msg) {
  return shell(title, `<div class="box"><h1>${esc(title)}</h1><p>${esc(msg)}</p></div>`);
}

function setupMissingPage(env) {
  const missing = ['OFORMO_URL', 'DASHBOARD_PASSWORD'].filter(k => !env[k]);
  return shell('Configurare incompletă', `<div class="box"><h1>Configurare incompletă</h1>
<p>Lipsesc secretele de mai jos. Adaugă-le în Cloudflare → acest Worker → <b>Settings</b> → <b>Variables and Secrets</b> → <b>Add</b> (tip „Secret”), apoi apasă <b>Deploy</b>.</p>
<ul>${missing.map(k => `<li><code>${k}</code></li>`).join('')}</ul></div>`);
}
